import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import javax.crypto.SecretKey;
import java.util.Date;

public class JwtService {
    private final SecretKey secretKey = Keys.hmacShaKeyFor(
        "mySecretKeyForJwtSigning1234567890".getBytes());

    public String generateToken(String username) {
        return Jwts.builder()
            .subject(username)  // sub claim
            .issuedAt(new Date())  // iat claim
            .expiration(new Date(System.currentTimeMillis() + 86400000))  // exp: 24h
            .signWith(secretKey)  // HMAC SHA256 signature
            .compact();  // builds header.payload.signature
    }

    public String extractUsername(String token) {
        return Jwts.parser()
            .verifyWith(secretKey)  // validates signature
            .build()
            .parseSignedClaims(token)
            .getPayload()
            .getSubject();  // extracts sub claim
    }
}

@Component
public class JwtAuthFilter extends OncePerRequestFilter {
    @Autowired private JwtService jwtService;
    @Autowired private UserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {
        var authHeader = request.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            filterChain.doFilter(request, response);  // no token, continue
            return;
        }
        var token = authHeader.substring(7);  // strip "Bearer "
        var username = jwtService.extractUsername(token);  // parse and validate
        if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
            var userDetails = userDetailsService.loadUserByUsername(username);
            if (jwtService.isTokenValid(token, userDetails)) {
                var authToken = new UsernamePasswordAuthenticationToken(
                    userDetails, null, userDetails.getAuthorities());
                SecurityContextHolder.getContext().setAuthentication(authToken);  // populate context
            }
        }
        filterChain.doFilter(request, response);
    }
}

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import javax.crypto.SecretKey;
import java.util.Date;
import java.util.Map;

public class JwtService {
    private final SecretKey key = Keys.hmacShaKeyFor(
        "mySecretKeyMustBe256BitsForHS256Algorithm".getBytes());

    public String generateToken(String username, List<String> roles) {
        var now = new Date();
        var expiration = new Date(now.getTime() + 3600000);  // 1 hour

        return Jwts.builder()
            .subject(username)  // sub: standard claim for user identity
            .issuedAt(now)  // iat: when token was created
            .expiration(expiration)  // exp: CRITICAL - when token expires
            .issuer("my-spring-app")  // iss: identifies token creator
            .claim("roles", roles)  // custom claim: user roles
            .claim("tokenType", "access")  // custom claim: distinguish access vs refresh
            .signWith(key)
            .compact();
    }

    public Map<String, Object> extractAllClaims(String token) {
        return Jwts.parser()
            .verifyWith(key)
            .build()
            .parseSignedClaims(token)
            .getPayload();  // returns all claims as a Map
    }
}

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import io.jsonwebtoken.Claims;
import javax.crypto.SecretKey;
import java.util.Date;

public class JwtService {
    private final SecretKey secretKey;

    public JwtService() {
        var keyString = "mySecretKeyForJwtSigning256BitsRequired";
        this.secretKey = Keys.hmacShaKeyFor(keyString.getBytes());
    }

    public String generateToken(String username, List<String> roles) {
        return Jwts.builder()
            .subject(username)
            .claim("roles", roles)  // custom claim
            .issuedAt(new Date())
            .expiration(new Date(System.currentTimeMillis() + 3600000))  // 1 hour
            .signWith(secretKey)  // HMAC SHA256
            .compact();
    }

    public Claims parseToken(String token) {
        return Jwts.parser()
            .verifyWith(secretKey)  // validates signature
            .build()
            .parseSignedClaims(token)  // throws exception if invalid
            .getPayload();
    }

    public boolean isTokenValid(String token) {
        try {
            parseToken(token);  // signature and expiry validated here
            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
